sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var body = request.body.data || {};

        var tableName = body.table_name;
        var tableSysId = body.table_sys_id;
        var fileName = body.file_name;
        var contentBase64 = body.content_base64;

        var service = new ProjectMCPAttachmentService();

        var result = service.addAttachment(
            tableName,
            tableSysId,
            fileName,
            contentBase64
        );

        if (!result.success) {
            response.setStatus(result.status || 500);

            gs.error(
                'project_mcp.attachment.add service error: ' +
                result.error
            );

            response.setBody({
                error: result.error
            });

            return;
        }

        response.setStatus(result.status || 201);
        response.setBody(result.data);

    } catch (e) {
        gs.error(
            'project_mcp.attachment.add error: ' +
            e.message
        );

        response.setStatus(500);
        response.setBody({
            error: 'Internal error processing request'
        });
    }
})(request, response);
